        <!-- Brain & Package Card -->\n          <article class=\"bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-5 shadow-sm space-y-3\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-xs font-mono font-bold uppercase tracking-wider text-slate-400\">Chiến thuật & Bộ não AI</span>\n              <span class=\"w-2 h-2 rounded-full bg-blue-500\"></span>\n            </div>\n            <div class=\"space-y-2 font-mono text-xs\">\n              <div class=\"p-3 bg-slate-50 rounded-xl border border-slate-100\">\n                <p id=\"brain-info\" class=\"text-slate-800 font-semibold\"></p>\n              </div>\n              <div class=\"p-3 bg-slate-50 rounded-xl border border-slate-100\">\n                <p id=\"hash\" class=\"text-slate-600 break-all\"></p>\n              </div>\n            </div>\n          </article>\n\n          <!-- Validated Versions -->\n          <article class=\"bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-5 shadow-sm space-y-3\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-xs font-mono font-bold uppercase tracking-wider text-slate-400\">Phiên bản đạt kiểm tra</span>\n              <span class=\"text-[10px] font-mono text-emerald-600 font-semibold\">SẴN SÀNG ĐẤU</span>\n            </div>\n            <ul id=\"versions\" class=\"space-y-2 font-mono text-xs max-h-56 overflow-y-auto custom-scroll\"></ul>\n          </article>\n\n          <!-- Drafts -->\n          <article class=\"bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-5 shadow-sm space-y-3\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-xs font-mono font-bold uppercase tracking-wider text-slate-400\">Bản nháp đang lưu</span>\n              <span class=\"text-[10px] font-mono text-slate-400\">CỤC BỘ</span>\n            </div>\n            <ul id=\"drafts\" class=\"space-y-2 text-xs max-h-56 overflow-y-auto custom-scroll\"></ul>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- PAGE 3: QUEUE & MATCHMAKING -->\n    <section id=\"queue\" hidden class=\"app-page app-queue relative flex-1 w-full p-6 overflow-y-auto custom-scroll\">\n      <div class=\"max-w-4xl mx-auto space-y-5\">\n        <div class=\"bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-5 shadow-sm space-y-3\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n            <div>\n              <h2 class=\"text-base font-extrabold text-slate-900\">Hàng chờ & Ghép cặp FIFO</h2>\n              <p class=\"text-xs text-slate-500 mt-0.5\">Mỗi tên người chơi có tối đa một lượt chờ. Hai tên khác nhau được ghép theo thứ tự đến trước.</p>\n            </div>\n            <div class=\"flex items-center gap-2\">\n              <button type=\"button\" id=\"submit\" class=\"py-2 px-4 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold transition shadow-sm\">\n                Nộp bản đã kiểm tra\n              </button>\n              <button type=\"button\" id=\"match\" class=\"py-2 px-4 rounded-xl bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold transition shadow-sm\">\n                Ghép cặp đang chờ\n              </button>\n            </div>\n          </div>\n\n          <div class=\"pt-3 border-t border-slate-100\">\n            <span class=\"text-[11px] font-mono uppercase tracking-wider text-slate-400 font-semibold block mb-2\">Thêm bot mẫu vào hàng chờ đối kháng:</span>\n            <div class=\"flex flex-wrap gap-2\" id=\"samples\"></div>\n          </div>\n        </div>\n\n        <div class=\"bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-5 shadow-sm space-y-3\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-xs font-mono font-bold uppercase tracking-wider text-slate-500\">Danh sách hàng chờ trực tiếp</span>\n            <span class=\"text-xs font-mono text-slate-400\">FIFO</span>\n          </div>\n          <ul id=\"queue-list\" class=\"space-y-2 font-mono text-xs\"></ul>\n        </div>\n      </div>\n    </section>\n\n    <!-- PAGE 4: BATTLE ARENA & REPLAY VIEWER -->\n    <section id=\"replay\" hidden class=\"app-replay relative flex-1 w-full h-full flex flex-col justify-between overflow-hidden\">\n      <!-- Background Arena Layer -->\n      <div class=\"replay__background absolute inset-0 bg-slate-950 bg-grid-cyber overflow-hidden pointer-events-none\">\n        <!-- Reticles & Arena Markings -->\n        <div class=\"absolute inset-4 rounded-2xl border border-slate-800/80 pointer-events-none shadow-[inset_0_0_120px_rgba(0,0,0,0.85)]\">\n          <div class=\"absolute top-3 left-3 w-4 h-4 border-t-2 border-l-2 border-cyan-500/50\"></div>\n          <div class=\"absolute top-3 right-3 w-4 h-4 border-t-2 border-r-2 border-cyan-500/50\"></div>\n          <div class=\"absolute bottom-3 left-3 w-4 h-4 border-b-2 border-l-2 border-cyan-500/50\"></div>\n          <div class=\"absolute bottom-3 right-3 w-4 h-4 border-b-2 border-r-2 border-cyan-500/50\"></div>\n          <div class=\"absolute inset-y-8 left-1/2 -translate-x-1/2 w-px border-l border-dashed border-slate-800/80 flex flex-col justify-between items-center py-6\">\n            <span class=\"font-mono text-[9px] text-cyan-500/40 tracking-widest uppercase rotate-90 origin-center\">Grid Meridian X-00</span>\n            <div class=\"w-24 h-24 rounded-full border border-cyan-500/20 flex items-center justify-center\">\n              <div class=\"w-1.5 h-1.5 rounded-full bg-cyan-400/50 animate-pulse\"></div>\n            </div>\n            <span class=\"font-mono text-[9px] text-cyan-500/40 tracking-widest uppercase rotate-90 origin-center\">Contact Sector 4</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- Center Canvas Layer -->\n      <div class=\"replay__canvas-layer absolute inset-0 flex items-center justify-center p-4\">\n        <canvas id=\"replay-canvas\" width=\"760\" height=\"760\" aria-label=\"Sân đấu. Đội A bên trái, đội B bên phải.\" class=\"max-w-full max-h-full object-contain rounded-xl border border-slate-800/80 shadow-2xl shadow-black/80\"></canvas>\n      </div>\n\n      <button type=\"button\" id=\"replay-hud-toggle\" aria-expanded=\"false\" aria-controls=\"replay-hud replay-panels replay-footer\" class=\"replay__hud-toggle absolute top-3 right-3 z-40 min-h-10 px-3 rounded-xl bg-slate-900/90 hover:bg-slate-800 text-white text-xs font-semibold border border-slate-700 shadow-lg transition\">\n        Hiện HUD\n      </button>\n\n      <!-- FLOATING TOP HUD (HEALTH / CORE STATUS / MATCH CLOCK) -->\n      <div id=\"replay-hud\" data-replay-hud hidden class=\"replay__hud relative z-20 w-full px-8 pt-4 flex justify-between items-start pointer-events-none shrink-0\">\n        <!-- LEFT HUD: BOT A -->\n        <div id=\"hud-a\" class=\"replay__hud-card replay__hud-a pointer-events-auto bg-white/95 backdrop-blur-md border border-slate-200/90 rounded-xl p-3.5 shadow-[0_4px_20px_-4px_rgba(225,29,72,0.12)] w-80\"></div>\n\n        <!-- CENTER HUD: MATCH CLOCK & STATUS -->\n        <div class=\"replay__clock pointer-events-auto bg-white/95 backdrop-blur-md border border-slate-200/90 rounded-2xl px-6 py-2 shadow-sm flex flex-col items-center\">\n          <div class=\"flex items-center gap-1.5 mb-0.5\">\n            <span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>\n            <span class=\"text-[10px] font-mono font-bold uppercase tracking-wider text-slate-400\">MÔ PHỎNG TRẬN ĐẤU</span>\n          </div>\n          <div id=\"replay-status\" role=\"status\" class=\"font-mono text-center\"></div>\n        </div>\n\n        <!-- RIGHT HUD: BOT B -->\n        <div id=\"hud-b\" class=\"replay__hud-card replay__hud-b pointer-events-auto bg-white/95 backdrop-blur-md border border-slate-200/90 rounded-xl p-3.5 shadow-[0_4px_20px_-4px_rgba(37,99,235,0.12)] w-80\"></div>\n      </div>\n\n      <!-- FLOATING SIDE PANELS (LEFT INSPECTOR & RIGHT EVENTS) -->\n      <div id=\"replay-panels\" data-replay-hud hidden class=\"replay__panels relative z-20 w-full px-8 flex justify-between items-center pointer-events-none my-auto\">\n        <!-- LEFT FLOATING PANEL: BOT INSPECTOR -->\n        <details class=\"replay__panel replay__panel--inspector responsive-panel pointer-events-auto w-72 bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-4 shadow-lg shadow-slate-200/50 flex flex-col gap-3\" data-responsive-panel>\n          <summary class=\"replay__panel-summary flex items-center justify-between pb-2 border-b border-slate-100\">\n            <div class=\"flex items-center gap-2\">\n              <div class=\"w-2 h-2 rounded-full bg-rose-500\"></div>\n              <span class=\"font-bold text-xs uppercase tracking-wider text-slate-700\">Bot Inspector</span>\n            </div>\n            <span class=\"font-mono text-[10px] text-slate-400\">ĐỘI A</span>\n          </summary>\n\n          <div class=\"replay__panel-body flex flex-col gap-3\">\n\n          <!-- Composition Breakdown -->\n          <div class=\"space-y-1.5 text-xs font-medium\" id=\"replay-bot-breakdown\">\n            <div class=\"flex justify-between items-center text-slate-600\">\n              <span class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 bg-rose-700 rounded-2xs inline-block\"></span>Búa (Solid)</span>\n              <span class=\"font-mono font-bold text-slate-800\" id=\"stat-hammer\">—</span>\n            </div>\n            <div class=\"flex justify-between items-center text-slate-600\">\n              <span class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 border border-rose-500 rounded-2xs inline-block\"></span>Kéo (Outline)</span>\n              <span class=\"font-mono font-bold text-slate-800\" id=\"stat-scissor\">—</span>\n            </div>\n            <div class=\"flex justify-between items-center text-slate-600\">\n              <span class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 border border-dashed border-amber-600 bg-amber-50 rounded-2xs inline-block\"></span>Bao (Dotted)</span>\n              <span class=\"font-mono font-bold text-slate-800\" id=\"stat-paper\">—</span>\n            </div>\n            <div class=\"flex justify-between items-center text-slate-600\">\n              <span class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 border border-dashed border-slate-400 bg-slate-100 rounded-2xs inline-block\"></span>Motor (Thrust)</span>\n              <span class=\"font-mono font-bold text-slate-800\" id=\"stat-motor\">—</span>\n            </div>\n          </div>\n\n          <!-- Physical Metrics -->\n          <div class=\"p-2.5 bg-slate-50 rounded-xl border border-slate-200/70 grid grid-cols-3 gap-1 text-center font-mono\">\n            <div>\n              <div class=\"text-[9px] text-slate-400\">TẢI</div>\n              <div class=\"text-xs font-bold text-slate-800 mt-0.5\" id=\"stat-load\">—</div>\n            </div>\n            <div class=\"border-x border-slate-200\">\n              <div class=\"text-[9px] text-slate-400\">MẢNH</div>\n              <div class=\"text-xs font-bold text-emerald-600 mt-0.5\" id=\"stat-pieces\">—</div>\n            </div>\n            <div>\n              <div class=\"text-[9px] text-slate-400\">LÕI HP</div>\n              <div class=\"text-xs font-bold text-rose-600 mt-0.5\" id=\"stat-core\">—</div>\n            </div>\n          </div>\n\n          <div class=\"grid grid-cols-2 gap-2 pt-1\">\n            <button type=\"button\" onclick=\"document.querySelector('[data-page=inspector]').click()\" class=\"py-1.5 px-3 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold transition border border-slate-200/80 flex items-center justify-center gap-1\">\n              Xem chi tiết\n            </button>\n            <button type=\"button\" onclick=\"document.querySelector('[data-page=editor]').click()\" class=\"py-1.5 px-3 rounded-lg bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold transition shadow-xs flex items-center justify-center gap-1\">\n              Sửa bot\n            </button>\n          </div>\n          </div>\n        </details>\n\n        <!-- RIGHT FLOATING PANEL: MATCH EVENTS & DAMAGE HEATMAP -->\n        <details class=\"replay__panel replay__panel--events responsive-panel pointer-events-auto w-72 bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/80 p-4 shadow-lg shadow-slate-200/50 flex flex-col gap-3\" data-responsive-panel>\n          <summary class=\"replay__panel-summary flex items-center justify-between pb-2 border-b border-slate-100\">\n            <div class=\"flex items-center gap-2\">\n              <span class=\"w-2 h-2 rounded-full bg-blue-500\"></span>\n              <span class=\"font-bold text-xs uppercase tracking-wider text-slate-700\">Sự kiện trận đấu</span>\n            </div>\n            <span class=\"font-mono text-[10px] text-slate-400\">LIVE FEED</span>\n          </summary>\n\n          <div class=\"replay__panel-body flex flex-col gap-3\">\n\n          <!-- Event Stream Log -->\n          <ul id=\"event-log\" class=\"space-y-1.5 font-mono text-[11px] custom-scroll max-h-44 overflow-y-auto pr-1\"></ul>\n\n          <!-- Mini Heatmap Preview -->\n          <div class=\"p-2.5 rounded-xl bg-slate-50 border border-slate-200/80\">\n            <div class=\"flex items-center justify-between mb-1.5\">\n              <span class=\"text-[10px] font-mono font-bold uppercase tracking-wider text-slate-500\">Tỷ lệ sát thương</span>\n              <span class=\"text-[9px] font-mono text-emerald-600 font-semibold\" id=\"heatmap-updated\">HEATMAP</span>\n            </div>\n            <div class=\"h-12 rounded-lg bg-white border border-slate-200/80 flex items-center justify-around px-3\">\n              <div class=\"flex flex-col items-center\">\n                <div class=\"w-6 h-6 rounded-full bg-rose-100 border border-rose-300 flex items-center justify-center text-[10px] font-bold text-rose-700\">A</div>\n                <span class=\"text-[9px] font-mono text-slate-500 mt-0.5\" id=\"dmg-pct-a\">50% DMG</span>\n              </div>\n              <div class=\"h-6 w-px bg-slate-200\"></div>\n              <div class=\"flex flex-col items-center\">\n                <div class=\"w-6 h-6 rounded-full bg-blue-100 border border-blue-300 flex items-center justify-center text-[10px] font-bold text-blue-800\">B</div>\n                <span class=\"text-[9px] font-mono text-slate-500 mt-0.5\" id=\"dmg-pct-b\">50% DMG</span>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"text-[10px] text-slate-400 text-center font-mono\">\n            Quy luật: Búa → Kéo → Bao (×2.0)\n          </div>\n          </div>\n        </details>\n      </div>\n\n      <!-- BOTTOM REPLAY TIMELINE & SCRUBBER BAR -->\n      <footer id=\"replay-footer\" data-replay-hud hidden class=\"replay__footer relative z-30 w-full px-8 pb-4\">\n        <div class=\"replay__controls bg-white/95 backdrop-blur-md rounded-2xl border border-slate-200/90 px-5 py-2.5 shadow-lg shadow-slate-200/40 flex items-center justify-between gap-4\">\n          <!-- Play / Pause & Steps -->\n          <div class=\"replay__playback flex items-center gap-2 shrink-0\">\n            <button type=\"button\" id=\"play\" class=\"w-9 h-9 rounded-xl bg-slate-900 hover:bg-slate-800 text-white flex items-center justify-center transition shadow-xs text-xs font-semibold\">\n              Phát\n            </button>\n            <button type=\"button\" id=\"back\" aria-label=\"Lùi một nhịp\" class=\"w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-bold transition border border-slate-200/80\">\n              −1\n            </button>\n            <button type=\"button\" id=\"forward\" aria-label=\"Tiến một nhịp\" class=\"w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-bold transition border border-slate-200/80\">\n              +1\n            </button>\n          </div>\n\n          <!-- Center Timeline Scrubber -->\n          <div class=\"replay__timeline flex-1 relative flex flex-col justify-center\">\n            <div class=\"relative w-full h-6 flex items-center group\">\n              <input id=\"seek\" type=\"range\" min=\"0\" value=\"0\" aria-label=\"Thanh thời gian\" class=\"w-full cursor-pointer\">\n            </div>\n            <div class=\"flex justify-between text-[10px] font-mono text-slate-400 px-0.5\">\n              <span>00:00</span>\n              <span>00:30</span>\n              <span>01:00</span>\n              <span>01:30</span>\n              <span>02:00</span>\n            </div>\n          </div>\n\n          <!-- Speed Controls -->\n          <div class=\"replay__speed flex items-center gap-1 shrink-0\">\n            <label class=\"text-[11px] font-mono text-slate-400\">Tốc độ:</label>\n            <select id=\"playback-speed\" class=\"px-2 py-1 text-xs font-mono font-bold rounded-lg bg-slate-100 border border-slate-200 outline-none\">\n              <option value=\"0.5\">0.5×</option>\n              <option value=\"1\" selected>1×</option>\n              <option value=\"2\">2×</option>\n              <option value=\"4\">4×</option>\n            </select>\n          </div>\n\n          <!-- Mode Toggle: Damage Map -->\n          <div class=\"replay__damage flex items-center gap-2 shrink-0 border-l border-slate-200 pl-3\">\n            <label class=\"flex items-center gap-1.5 text-xs font-semibold text-slate-600 hover:text-slate-900 cursor-pointer\">\n              <input id=\"damage\" type=\"checkbox\" class=\"w-3.5 h-3.5 rounded accent-rose-600\">\n              <span>Bản đồ nhiệt</span>\n            </label>\n          </div>\n        </div>\n\n        <!-- Saved Replays Drawer / List -->\n        <div class=\"replay__saved mt-2 p-3 bg-white/90 backdrop-blur-sm rounded-xl border border-slate-200/80 flex items-center gap-3 overflow-x-auto custom-scroll\">\n          <span class=\"text-[11px] font-mono uppercase tracking-wider text-slate-400 font-bold shrink-0\">Trận đã lưu:</span>\n          <div id=\"replay-list\" class=\"flex items-center gap-2\"></div>\n        </div>\n      </footer>\n    </section>\n\n  </main>\n\n  <!-- JSON IMPORT / EXPORT MODAL -->\n  <div id=\"json-modal\" hidden style=\"display: none;\" class=\"fixed inset-0 z-50 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center p-4\">\n    <div class=\"json-modal__card bg-white rounded-2xl border border-slate-200 shadow-2xl max-w-2xl w-full p-6 flex flex-col gap-4\">\n      <div class=\"flex items-center justify-between pb-3 border-b border-slate-100\">\n        <div>\n          <h3 class=\"font-extrabold text-base text-slate-900\">Nhập / Xuất mã Bot JSON</h3>\n          <p class=\"text-xs text-slate-500 mt-0.5\">Dán nội dung JSON định dạng BotDefinition hoặc tải tệp .json từ máy tính.</p>\n        </div>\n        <button type=\"button\" id=\"json-close-btn\" class=\"w-8 h-8 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 flex items-center justify-center text-sm font-bold\">✕</button>\n      </div>\n\n      <div class=\"flex items-center justify-between gap-3\">\n        <label class=\"px-3 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold cursor-pointer border border-slate-200 transition flex items-center gap-1.5\">\n          <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n          <span>Chọn tệp .json từ máy</span>\n          <input type=\"file\" id=\"json-file-input\" accept=\".json\" class=\"hidden\">\n        </label>\n        <span class=\"text-[11px] font-mono text-slate-400\">Định dạng BotDefinition v1.0.0</span>\n      </div>\n\n      <textarea id=\"json-textarea\" rows=\"12\" spellcheck=\"false\" placeholder=\"Dán mã JSON của bot vào đây...\" class=\"w-full p-3 font-mono text-xs rounded-xl bg-slate-50 border border-slate-200 focus:bg-white focus:border-slate-900 outline-none custom-scroll resize-y\"></textarea>\n\n      <div class=\"json-modal__actions flex items-center justify-between pt-2 border-t border-slate-100\">\n        <button type=\"button\" id=\"json-copy-btn\" class=\"px-3 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold transition border border-slate-200 flex items-center gap-1.5\">\n          <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n          Sao chép JSON\n        </button>\n        <div class=\"flex items-center gap-2\">\n          <button type=\"button\" id=\"json-cancel-btn\" class=\"px-4 py-2 rounded-xl text-slate-600 hover:bg-slate-100 text-xs font-semibold transition\">Hủy</button>\n          <button type=\"button\" id=\"json-apply-btn\" class=\"px-4 py-2 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold transition shadow-xs flex items-center gap-1.5\">\n            <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n            Áp dụng mã bot\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <p id=\"toast\" role=\"status\"></p>\n  <p id=\"selftest\" hidden></p>\n\n  <script type=\"importmap\">\n  {\n    \"imports\": {\n      \"@prompt-chien/ui\": \"https://api.kythuatvang.com/panel/pkg